update_rule.pseudocode:
on_init:
  load social_network.json into raw adjacency per agent per layer
  for each layer in {family, work_school, community}:
    for each agent i:
      neighbors = unique(raw[i][layer]) - {i}
      if symmetrize_edges:
        for j in neighbors:
          add i to raw[j][layer]
      store neighbors[i][layer]
  if layer_overlap_policy == 'merge_with_weight_sum':
    merged_weight[i][j] = sum(layer_weight for layers where edge exists)
  compute degree_by_layer[i][layer] = |neighbors[i][layer]|
  return graphs and degree_by_layer

for each agent i:
  for each layer L in {family, work_school, community}:
    N = neighbors[i][L]
    if |N| == 0:
      peer_mask_fraction[i][L] = 0
      info_contacts[i][L] = 0
    else:
      mask_count = sum(is_mask_wearing[j] for j in N)
      info_count = sum(received_info[j] for j in N)
      peer_mask_fraction[i][L] = (mask_count / |N|) * w_L * mobility_rate
      info_contacts[i][L] = info_count
emit exposure signals
